class SafiImeService : InputMethodService() {
 companion object { var active:SafiImeService?=null; fun insertVoiceResult(s:String){active?.currentInputConnection?.commitText(s,1)} }
 private var bangla=false; private var symbols=false; private var shift=false; private var theme=0; private var scale=1f
 private val palettes=mutableListOf(intArrayOf(0xFF000000.toInt(),0xFF1C1D22.toInt(),-1,0xFFFFC400.toInt(),0xFF1F568B.toInt(),0xFFD91F35.toInt(),0xFFF4F0E8.toInt()),intArrayOf(0xFF101820.toInt(),0xFF263642.toInt(),-1,0xFF12B886.toInt(),0xFF087F8C.toInt(),0xFF2B3741.toInt(),-1),intArrayOf(0xFFF2F4F7.toInt(),-1,0xFF202733.toInt(),0xFFB9D8FF.toInt(),0xFFFFD8E7.toInt(),0xFFE9E0FF.toInt(),-1),intArrayOf(0xFF160E2A.toInt(),0xFF2D1B4E.toInt(),-1,0xFF9B5DE5.toInt(),0xFF00BBF9.toInt(),0xFFF15BB5.toInt(),0xFF3A245A.toInt()),intArrayOf(0xFF071D17.toInt(),0xFF123C30.toInt(),-1,0xFF57CC99.toInt(),0xFF38A3A5.toInt(),0xFF22577A.toInt(),0xFFD8F3DC.toInt()),intArrayOf(0xFF171717.toInt(),0xFF303030.toInt(),-1,0xFFBDBDBD.toInt(),0xFF616161.toInt(),0xFF424242.toInt(),0xFFF5F5F5.toInt()),intArrayOf(0xFFFFF4E6.toInt(),0xFFFFE1C2.toInt(),0xFF442B1C.toInt(),0xFFE76F51.toInt(),0xFFF4A261.toInt(),0xFFB23A48.toInt(),0xFFFFFFFF.toInt()),intArrayOf(0xFF07111F.toInt(),0xFF102A43.toInt(),-1,0xFF00D9FF.toInt(),0xFF3A86FF.toInt(),0xFFFF006E.toInt(),0xFFE0FBFC.toInt()),intArrayOf(0xFF121212.toInt(),0xFF252525.toInt(),-1,0xFF7C4DFF.toInt(),0xFF00BFA5.toInt(),0xFFFF5252.toInt(),0xFFF5F5F5.toInt()))
 private val prefs by lazy { getSharedPreferences("safi",Context.MODE_PRIVATE) }; private val shortcuts=linkedMapOf<String,String>(); private val clips=mutableListOf<String>()
 override fun onCreate(){super.onCreate();active=this;theme=prefs.getInt("theme",0).coerceIn(0,palettes.lastIndex);try{val custom=prefs.getString("custom_palette","")!!.split(",").map{it.toLong(16).toInt()};if(custom.size==7)palettes[8]=custom.toIntArray()}catch(_:Exception){};scale=prefs.getFloat("scale",1f).coerceIn(.75f,1.25f);try{val j=JSONObject(prefs.getString("shortcuts","{}")!!);j.keys().forEach{shortcuts[it]=j.getString(it)}}catch(_:Exception){};try{val a=JSONArray(prefs.getString("clips","[]")!!);for(i in 0 until a.length())clips.add(a.getString(i))}catch(_:Exception){};downloadLanguagePackIfNeeded() }
 override fun onCreateInputView():View=keyboard()
 private fun keyboard():LinearLayout { val p=palettes[theme]; return LinearLayout(this).apply { orientation=1;setPadding(dp(3),dp(4),dp(3),dp(4));setBackgroundColor(p[0])
  val bar=LinearLayout(this@SafiImeService).apply{gravity=Gravity.CENTER}
  listOf("⋯","↶","✎","▤","☺","🌐","🎙","🎨").forEachIndexed{i,s->key(bar,s,p[2],p[1],1f,true){when(i){0->tools();1->currentInputConnection?.deleteSurroundingText(1,0);2->dictionary();3->clipboard();4->emoji();5->{bangla=!bangla;refresh()};6->voice();7->{theme=(theme+1)%palettes.size;prefs.edit().putInt("theme",theme).apply();refresh()}}}}
  addView(bar)
  val rows=if(symbols) listOf(listOf("1","2","3","4","5","6","7","8","9","0"),listOf("@","#","$","%","&","-","+","(",")","/"),listOf("=","*","'",";",":","!","?")) else if(bangla) listOf(listOf("ক","খ","গ","ঘ","ঙ","চ","ছ","জ","ঝ","ঞ"),listOf("ট","ঠ","ড","ঢ","ণ","ত","থ","দ","ধ","ন"),listOf("প","ফ","ব","ভ","ম","য","র","ল","স")) else listOf("qwertyuiop".map{it.toString()},"asdfghjkl".map{it.toString()},"zxcvbnm".map{it.toString()})
  rows.forEachIndexed{idx,row->val r=LinearLayout(this@SafiImeService).apply{gravity=Gravity.CENTER;if(idx==1&&!symbols)setPadding(dp(8),0,dp(8),0)};if(idx==2&&!symbols)key(r,"⇧",p[2],p[3],1.1f){shift=!shift;refresh()};row.forEachIndexed{n,ch->val label=if(shift&&!bangla&&!symbols)ch.uppercase() else ch;val bg=if(theme==0) listOf(p[3],p[4],p[1],p[6],p[5])[(idx*3+n)%5] else if(n%4==0)p[3] else p[1];key(r,label,if(bg==p[6]||bg==p[3]||bg==p[5])Color.BLACK else p[2],bg){type(label)}};if(idx==2&&!symbols)key(r,"⌫",p[2],p[1],1.2f){currentInputConnection?.deleteSurroundingText(1,0)};addView(r)}
  val b=LinearLayout(this@SafiImeService).apply{gravity=Gravity.CENTER}
  key(b,"?123",p[2],p[5]){symbols=!symbols;refresh()};key(b,"☺",p[2],p[4]){emoji()};key(b,",",p[2],p[1]){put(",")};key(b,"বাংলা/EN",p[2],p[1],1.3f){bangla=!bangla;refresh()};key(b,"space",p[2],p[1],2.4f){if(bangla)convertLast();put(" ")};key(b,".",p[2],p[1]){put(".");expand()};key(b,"↵",p[2],p[5],1.2f){expand();val a=currentInputEditorInfo?.imeOptions?.and(EditorInfo.IME_MASK_ACTION)?:0;if(a!=0)currentInputConnection?.performEditorAction(a) else put("\n")};addView(b)
 } }
 private fun key(row:LinearLayout,label:String,fg:Int,bg:Int,w:Float=1f,small:Boolean=false,act:()->Unit){val v=TextView(this).apply{text=label;textSize=if(small||label.length>3)12f*scale else 18f*scale;gravity=Gravity.CENTER;setTextColor(fg);background=GradientDrawable().apply{setColor(bg);cornerRadius=10f*resources.displayMetrics.density};setPadding(dp(1),dp(if(small)7 else 9),dp(1),dp(if(small)7 else 9));setOnClickListener{act()}};row.addView(v,LinearLayout.LayoutParams(0,dp(((if(small)36 else 43)*scale).toInt()),w).apply{setMargins(dp(2),dp(3),dp(2),dp(3))})}
 private fun dp(v:Int):Int=(v*resources.displayMetrics.density).toInt().coerceAtLeast(1)
 private fun put(s:String){currentInputConnection?.commitText(s,1)}
 private fun refresh(){setInputView(keyboard())}
 private fun type(s:String){put(s);suggest()}
 private fun tools(){val v=panel("Safi Smart Tools");listOf("Themes & customize","Keyboard size","Phonetic dictionary","Translate বাংলা → English","Translate English → বাংলা","Voice typing","GIF search","Emoji","Back").forEachIndexed{i,s->v.addView(Button(this).apply{text=s;setOnClickListener{when(i){0->themePanel();1->sizePanel();2->dictionary();3->translate("bn","en");4->translate("en","bn");5->voice();6->gif();7->emoji();else->refresh()}}})};setInputView(v)}
 private fun panel(title:String)=LinearLayout(this).apply{orientation=1;setPadding(8,6,8,6);setBackgroundColor(palettes[theme][0]);addView(TextView(this@SafiImeService).apply{text=title;textSize=18f;setTextColor(palettes[theme][2])})}
 private fun sizePanel(){val v=panel("Keyboard size");val value=TextView(this).apply{text="Size: ${(scale*100).toInt()}%";textSize=16f;gravity=Gravity.CENTER;setTextColor(palettes[theme][2])};v.addView(value);v.addView(SeekBar(this).apply{max=75;progress=((scale-.75f)*100).toInt().coerceIn(0,max);setOnSeekBarChangeListener(object:SeekBar.OnSeekBarChangeListener{override fun onProgressChanged(s:SeekBar?,n:Int,u:Boolean){scale=.75f+n/100f;value.text="Size: ${(scale*100).toInt()}%";prefs.edit().putFloat("scale",scale).apply()};override fun onStartTrackingTouch(s:SeekBar?){};override fun onStopTrackingTouch(s:SeekBar?){refresh()}})});val controls=LinearLayout(this@SafiImeService).apply{gravity=Gravity.CENTER};listOf("−","Reset 100%","+").forEachIndexed{i,label->controls.addView(Button(this@SafiImeService).apply{text=label;setOnClickListener{scale=when(i){0->(scale-.1f).coerceAtLeast(.75f);1->1f;else->(scale+.1f).coerceAtMost(1.5f)};prefs.edit().putFloat("scale",scale).apply();refresh()}})};v.addView(controls);v.addView(Button(this).apply{text="Apply";setOnClickListener{refresh()}});setInputView(v)}
 private fun dictionary(){val v=panel("Dictionary: KL → খুলনা");val k=EditText(this).apply{hint="Shortcut (KL)";setSingleLine()};val x=EditText(this).apply{hint="Expanded text (খুলনা)";setSingleLine()};v.addView(k);v.addView(x);v.addView(Button(this).apply{text="Save";setOnClickListener{if(k.text.isNotBlank()&&x.text.isNotBlank()){shortcuts[k.text.toString().trim().uppercase()]=x.text.toString().trim();val j=JSONObject();shortcuts.forEach{(a,b)->j.put(a,b)};prefs.edit().putString("shortcuts",j.toString()).apply();Toast.makeText(this@SafiImeService,"Saved",0).show();refresh()}}});shortcuts.forEach{(a,b)->v.addView(TextView(this).apply{text="$a → $b";setTextColor(palettes[theme][2])})};v.addView(Button(this).apply{text="Back";setOnClickListener{refresh()}});setInputView(v)}
 private fun expand(){val before=currentInputConnection?.getTextBeforeCursor(80,0)?.toString().orEmpty();val token=before.takeLastWhile{!it.isWhitespace()&&it !in ".,!?;:"};val value=shortcuts[token.uppercase()]?:mapOf("teh" to "the","adn" to "and","recieve" to "receive","definately" to "definitely","কেমনো" to "কেমন","আমারর" to "আমার")[token.lowercase()];if(value!=null){currentInputConnection?.deleteSurroundingText(token.length,0);put(value)}}
 private fun suggest(){val before=currentInputConnection?.getTextBeforeCursor(80,0)?.toString().orEmpty();val token=before.takeLastWhile{!it.isWhitespace()&&it !in ".,!?;:"};if(token.isBlank())return;val correction=mapOf("teh" to "the","adn" to "and","recieve" to "receive","কেমনো" to "কেমন")[token.lowercase()]?:return;val v=panel("Suggested: $correction");v.addView(Button(this).apply{text=correction;setOnClickListener{currentInputConnection?.deleteSurroundingText(token.length,0);put(correction+" ");refresh()}});v.addView(Button(this).apply{text="Back";setOnClickListener{refresh()}}); }
 private fun convertLast(){val before=currentInputConnection?.getTextBeforeCursor(100,0)?.toString().orEmpty();val trailing=before.takeLastWhile{!it.isWhitespace()};val punctuation=trailing.takeLastWhile{it in ",.!?;:"};val token=trailing.dropLast(punctuation.length);if(token.isBlank()||token.any{it.code>127})return;val builtIn=mapOf("ami" to "আমি","akhon" to "এখন","ekhon" to "এখন","jabo" to "যাবো","tui" to "তুই","cole" to "চলে","chole" to "চলে","ja" to "যা","tumi" to "তুমি","apni" to "আপনি","amar" to "আমার","tomar" to "তোমার","amra" to "আমরা","kemon" to "কেমন","bhalo" to "ভালো","valo" to "ভালো","bangla" to "বাংলা","dhaka" to "ঢাকা","shundor" to "সুন্দর","sundor" to "সুন্দর","ki" to "কি","keno" to "কেন","hobe" to "হবে","na" to "না","dhonnobad" to "ধন্যবাদ");val pack=try{JSONObject(prefs.getString("phonetic_pack","{}")!!)}catch(_:Exception){JSONObject()};val out=pack.optJSONObject("words")?.optString(token.lowercase())?.takeIf{it.isNotBlank()&&it!="null"}?:builtIn[token.lowercase()]?:basicTransliterate(token);if(out.isNotBlank()&&out!=token){currentInputConnection?.deleteSurroundingText(trailing.length,0);put(out+punctuation)}}
 private fun basicTransliterate(s:String):String{val consonants=listOf("kh" to "খ","gh" to "ঘ","chh" to "ছ","ch" to "চ","jh" to "ঝ","sh" to "শ","th" to "থ","dh" to "ধ","ph" to "ফ","bh" to "ভ","ng" to "ঙ","ny" to "ঞ","k" to "ক","g" to "গ","j" to "জ","t" to "ত","d" to "দ","n" to "ন","p" to "প","b" to "ব","m" to "ম","r" to "র","l" to "ল","s" to "স","h" to "হ","y" to "য়","f" to "ফ","v" to "ভ","z" to "জ","c" to "চ","q" to "ক","w" to "ও","x" to "ক্স");val vowels=listOf("oi" to "ঐ","ou" to "ঔ","ee" to "ঈ","oo" to "ঊ","aa" to "আ","a" to "আ","i" to "ই","e" to "এ","u" to "উ","o" to "ও");val src=s.lowercase();val out=StringBuilder();var i=0;var hasConsonant=false;while(i<src.length){val v=vowels.firstOrNull{src.startsWith(it.first,i)};if(v!=null){out.append(if(hasConsonant)mapOf("oi" to "ৈ","ou" to "ৌ","ee" to "ী","oo" to "ূ","aa" to "া","a" to "া","i" to "ি","e" to "ে","u" to "ু","o" to "ো")[v.first] else v.second);i+=v.first.length;hasConsonant=false;continue};val con=consonants.firstOrNull{src.startsWith(it.first,i)};if(con!=null){out.append(con.second);i+=con.first.length;hasConsonant=true;continue};out.append(src[i]);i++};return out.toString()}
 private fun downloadLanguagePackIfNeeded(){if(prefs.getString("phonetic_pack","")!!.isNotBlank())return;Thread{try{val conn=(URL("https://raw.githubusercontent.com/mdsafiislam994-max/safi-keyboard-android/main/language-packs/bn-phonetic.json").openConnection() as HttpURLConnection).apply{connectTimeout=5000;readTimeout=7000;requestMethod="GET"};val data=conn.inputStream.bufferedReader().use{it.readText()};if(JSONObject(data).optJSONObject("words")!=null){prefs.edit().putString("phonetic_pack",data).apply()};conn.disconnect()}catch(_:Exception){}}.start()}
 private fun themePanel(){val v=panel("Safi Themes · choose a style");val names=listOf("Midnight Pop","Forest Mint","Soft Pastel","Violet Glow","Forest","Mono","Sunset","Neon Blue","My Custom Theme");names.forEachIndexed{i,n->v.addView(Button(this).apply{text=n;setOnClickListener{theme=i;prefs.edit().putInt("theme",theme).apply();refresh()}})};val fields=listOf("Background","Key color","Text color","Accent color","Secondary color","Danger color","Light key color");val defaults=palettes[8];val edits=fields.mapIndexed{i,label->EditText(this).apply{hint="$label · #RRGGBB";setSingleLine();setText("#"+Integer.toHexString(defaults[i]).takeLast(6).uppercase())}};edits.forEach{v.addView(it)};v.addView(Button(this).apply{text="Save custom theme";setOnClickListener{try{val colors=edits.map{Color.parseColor(it.text.toString().trim())}.toIntArray();palettes[8]=colors;prefs.edit().putString("custom_palette",colors.joinToString(","){Integer.toHexString(it)}).putInt("theme",8).apply();theme=8;refresh()}catch(_:Exception){Toast.makeText(this@SafiImeService,"প্রতিটি রঙ #RRGGBB ফরম্যাটে দিন",Toast.LENGTH_LONG).show()}}});v.addView(Button(this).apply{text="Back";setOnClickListener{refresh()}});setInputView(ScrollView(this).apply{addView(v)})}
 private fun clipboard(){val v=panel("Clipboard history · tap to insert");val cm=getSystemService(Context.CLIPBOARD_SERVICE) as ClipboardManager;if(cm.hasPrimaryClip())cm.primaryClip?.getItemAt(0)?.coerceToText(this)?.toString()?.let{if(it.isNotBlank()){clips.remove(it);clips.add(0,it);prefs.edit().putString("clips",JSONArray(clips.take(20)).toString()).apply()}};clips.take(15).forEach{t->v.addView(Button(this).apply{text=t.take(80);setOnClickListener{put(t);refresh()}})};v.addView(Button(this).apply{text="Clear";setOnClickListener{clips.clear();prefs.edit().putString("clips","[]").apply();clipboard()}});v.addView(Button(this).apply{text="Back";setOnClickListener{refresh()}});setInputView(v)}
 private fun emoji(){val v=panel("Emoji");listOf("😀","😃","😂","🥹","😊","😍","🥰","😎","😭","🙏","👍","🔥","❤️","✨","🎉","🌸","🌿","💯","🤝","🤔","🙌","💙","🥳","🤩").chunked(6).forEach{g->val r=LinearLayout(this@SafiImeService).apply{gravity=Gravity.CENTER};g.forEach{e->key(r,e,-1,palettes[theme][1]){put(e);refresh()}};v.addView(r)};v.addView(Button(this).apply{text="Back";setOnClickListener{refresh()}});setInputView(v)}
 private fun gif(){try{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse("https://giphy.com/")).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}catch(_:Exception){}}
 private fun translate(a:String,b:String){val text=currentInputConnection?.getTextBeforeCursor(300,0)?.toString().orEmpty().trim();if(text.isBlank()){Toast.makeText(this,"আগে কিছু লিখুন",0).show();return};val url="https://translate.google.com/?sl=$a&tl=$b&text="+Uri.encode(text)+"&op=translate";startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}
 private fun voice(){try{startActivity(Intent(this,VoiceInputActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}catch(_:Exception){Toast.makeText(this,"Voice typing unavailable",0).show()}}
}